<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Kanban Board</title>
<style>
    body {
        font-family: Arial, Helvetica, sans-serif;
        background:#f4f4f4;
        margin:0;
        padding:20px;
    }
    #controls {
        margin-bottom:20px;
    }
    #new-card {
        width:60%;
        padding:6px;
        font-size:14px;
    }
    #add-card{
        padding:6px 12px;
        font-size:14px;
        cursor:pointer;
    }
    .board {
        display:flex;
        gap:15px;
    }
    .column {
        background:#fff;
        border:1px solid #ddd;
        border-radius:4px;
        flex:1;
        display:flex;
        flex-direction:column;
        max-width:320px;
        min-height:400px;
    }
    .column h2 {
        margin:0;
        padding:10px;
        background:#eee;
        font-size:1.2rem;
        border-bottom:1px solid #ddd;
        user-select:none;
    }
    .column .card-container {
        padding:10px;
        flex-grow:1;
        min-height:30px;
    }
    .card {
        background:#fafafa;
        border:1px solid #ccc;
        border-radius:4px;
        padding:8px;
        margin-bottom:8px;
        cursor:grab;
        display:flex;
        justify-content:space-between;
        align-items:center;
    }
    .card:active {
        cursor:grabbing;
    }
    .card-del {
        background:none;
        border:none;
        color:#c00;
        font-weight:bold;
        cursor:pointer;
        font-size:16px;
        line-height:1;
    }
    .card-del:hover {
        color:#f00;
    }
    .highlight {
        background:#e0ffe0;
    }
</style>
</head>
<body>

<div id="controls">
    <input type="text" id="new-card" placeholder="New task title">
    <button id="add-card">Add</button>
</div>

<div class="board">
    <div class="column" id="col-todo">
        <h2>To Do (<span class="count">0</span>)</h2>
        <div class="card-container"></div>
    </div>
    <div class="column" id="col-doing">
        <h2>Doing (<span class="count">0</span>)</h2>
        <div class="card-container"></div>
    </div>
    <div class="column" id="col-done">
        <h2>Done (<span class="count">0</span>)</h2>
        <div class="card-container"></div>
    </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', () => {
    const COL_IDS = ['col-todo','col-doing','col-done'];
    const STORAGE_KEY = 'kanbanBoard';

    /*** UTILITIES ***/
    function uid(){
        return 'c'+Date.now()+Math.random().toString(36).substr(2,5);
    }

    function createCardElement(id, title){
        const card = document.createElement('div');
        card.className = 'card';
        card.draggable = true;
        card.id = id;

        const txt = document.createElement('span');
        txt.textContent = title;
        const delBtn = document.createElement('button');
        delBtn.className = 'card-del';
        delBtn.innerHTML = '&times;';
        delBtn.title = 'Delete';

        delBtn.addEventListener('click', () => {
            card.remove();
            updateCounts();
            saveState();
        });

        card.appendChild(txt);
        card.appendChild(delBtn);

        card.addEventListener('dragstart', e => {
            e.dataTransfer.setData('text/plain', card.id);
            e.dataTransfer.effectAllowed = 'move';
        });

        return card;
    }

    function addCard(title, columnId='col-todo', id=null){
        if(!title.trim()) return;
        const cardId = id || uid();
        const card = createCardElement(cardId, title);
        const container = document.querySelector(`#${columnId} .card-container`);
        container.appendChild(card);
        updateCounts();
        saveState();
    }

    function updateCounts(){
        COL_IDS.forEach(colId=>{
            const cntEl = document.querySelector(`#${colId} .count`);
            const num = document.querySelectorAll(`#${colId} .card`).length;
            cntEl.textContent = num;
        });
    }

    function saveState(){
        const state = {};
        COL_IDS.forEach(colId=>{
            const cards = [];
            const container = document.querySelector(`#${colId} .card-container`);
            container.querySelectorAll('.card').forEach(card=>{
                cards.push({
                    id: card.id,
                    title: card.querySelector('span').textContent
                });
            });
            state[colId] = cards;
        });
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }

    function loadState(){
        const raw = localStorage.getItem(STORAGE_KEY);
        if(!raw) return;
        try{
            const state = JSON.parse(raw);
            COL_IDS.forEach(colId=>{
                const container = document.querySelector(`#${colId} .card-container`);
                container.innerHTML = '';
                (state[colId]||[]).forEach(obj=>{
                    const card = createCardElement(obj.id, obj.title);
                    container.appendChild(card);
                });
            });
            updateCounts();
        }catch(e){
            console.error('Failed to load board state:', e);
        }
    }

    /*** DRAG & DROP HANDLERS ***/
    function setupColumnDnD(column){
        column.addEventListener('dragover', e => {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move';
        });
        column.addEventListener('drop', e => {
            e.preventDefault();
            const cardId = e.dataTransfer.getData('text/plain');
            const card = document.getElementById(cardId);
            if(card && !column.contains(card)){
                const container = column.querySelector('.card-container');
                container.appendChild(card);
                updateCounts();
                saveState();
            }
        });
        column.addEventListener('dragenter', e => {
            e.preventDefault();
            column.classList.add('highlight');
        });
        column.addEventListener('dragleave', () => {
            column.classList.remove('highlight');
        });
        column.addEventListener('drop', () => {
            column.classList.remove('highlight');
        });
    }

    /*** INITIALISATION ***/
    // Setup DnD on columns
    COL_IDS.forEach(id => {
        const col = document.getElementById(id);
        setupColumnDnD(col);
    });

    // Add card button
    document.getElementById('add-card').addEventListener('click', () => {
        const inp = document.getElementById('new-card');
        const title = inp.value.trim();
        if(title){
            addCard(title,'col-todo');
            inp.value = '';
        }
    });

    // Enter key on input
    document.getElementById('new-card').addEventListener('keypress', e => {
        if(e.key === 'Enter'){
            document.getElementById('add-card').click();
        }
    });

    // Load persisted state
    loadState();
});
</script>

</body>
</html>
